import { invoke, isTauri } from "@tauri-apps/api/core";

/**
 * Saves generated bytes (exports, PDFs). In the desktop app this opens the native
 * Save dialog; in a browser it triggers a download. Resolves to false if cancelled.
 */
export async function saveFile(fileName: string, data: Blob, filter: { name: string; extensions: string[] }) {
  if (isTauri()) {
    const bytes = new Uint8Array(await data.arrayBuffer());
    const path = await invoke<string | null>("save_file", {
      defaultName: fileName,
      contents: Array.from(bytes),
      filterName: filter.name,
      extensions: filter.extensions,
    });
    return path !== null;
  }
  const url = URL.createObjectURL(data);
  const a = document.createElement("a");
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
  return true;
}

/** "Leads 2026-10-30" style names. */
export function datedName(base: string, ext: string) {
  return `${base} ${new Date().toISOString().slice(0, 10)}.${ext}`;
}
